     8	 */
     9	import type { Simulation } from './engine';
    10	import { gradeAt } from './ore';
    11	import { MATERIALS, type DumpSite, type Excavator, type Material, type StrategyName, type Truck } from './types';
    12	
    13	export interface DispatchStrategy {
    14	  readonly name: StrategyName;
    15	  /** Выбрать экскаватор для порожнего самосвала. */
    16	  choose(sim: Simulation, truck: Truck): number;
    17	  /** Реакция на поломку экскаватора. */
