    23	}
    24	
    25	export class FixedStrategy implements DispatchStrategy {
    26	  readonly name = 'fixed' as const;
    27	
    28	  choose(_sim: Simulation, truck: Truck): number {
    29	    return truck.fixedEx;
    30	  }
    31	}
    32	
    33	export interface Evaluation {
    34	  best: number;
    35	  /** Оценка (с) для каждого экскаватора: меньше — лучше. */
    36	  scores: number[];
    37	  /** Ожидаемое время до начала погрузки, с. */
    38	  waits: number[];
    39	  bonus: Record<Material, number>;
    40	}
    41	
    42	export class SmartStrategy implements DispatchStrategy {
    43	  readonly name = 'smart' as const;
    44	
    45	  /**
    46	   * Самосвал по умолчанию остаётся на своей «петле» (стартовое закрепление — как у плановика),
    47	   * но перезакрепляется, если другой экскаватор даёт выигрыш больше порога: очередь, поломка,
    48	   * отставание от плана, угроза простоя дробилки.
    49	   */
    50	  choose(sim: Simulation, truck: Truck): number {
    51	    const ev = this.evaluate(sim, truck);
    52	    const home = truck.homeEx;
    53	    if (ev.best !== home && !(ev.scores[home] - ev.scores[ev.best] <= sim.cfg.smart.stickinessSec)) truck.homeEx = ev.best;
    54	    return truck.homeEx;
    55	  }
