    57	  evaluate(sim: Simulation, truck: Truck): Evaluation {
    58	    const { node, extra } = sim.routeOrigin(truck);
    59	    const dist = sim.router.from(node).dist;
    60	    const v = sim.speedEmpty;
    61	    const now = sim.now;
    62	
    63	    // Прогноз прибытия других самосвалов к каждому экскаватору: порожние — по оставшемуся пути,
    64	    // гружёные — вернутся на свою петлю после разгрузки.
    65	    const arrivals: number[][] = sim.excavators.map(() => []);
    66	    for (const o of sim.trucks) {
    67	      if (o === truck) continue;
    68	      if (o.dest?.kind === 'excavator') {
    69	        if (o.state === 'empty') arrivals[o.dest.id].push(now + sim.remainingDistance(o) / v);
    70	        else if (o.state === 'broken' && o.resumeState === 'empty')
    71	          arrivals[o.dest.id].push(now + o.timer + sim.remainingDistance(o) / v);
    72	      } else if (o.dest?.kind === 'dump' && o.loadT > 0) {
    73	        const dump = sim.dumps[o.dest.id];
    74	        const haul = o.state === 'loaded' || o.state === 'broken' ? sim.remainingDistance(o) / sim.speedLoaded : 0;
    75	        const repair = o.state === 'broken' ? o.timer : 0;
    76	        const back = sim.router.distance(dump.node, sim.excavators[o.homeEx].node) / v;
    77	        arrivals[o.homeEx].push(now + repair + haul + dump.dumpTimeSec + back);
    78	      }
    79	    }
    80	
    81	    const bonus = this.materialBonus(sim, truck);
    82	    const share = this.shareBonus(sim, truck);
    83	    const grade = this.gradeBonus(sim, truck);
    84	    const scores: number[] = [];
    85	    const waits: number[] = [];
    86	    let best = truck.fixedEx;
    87	    let bestScore = Infinity;
    88	    for (const ex of sim.excavators) {
    89	      const d = dist[ex.node] + extra;
    90	      if (!Number.isFinite(d)) {
    91	        scores.push(Infinity);
    92	        waits.push(Infinity);
    93	        continue;
    94	      }
    95	      const arrive = now + d / v;
    96	      const lt = sim.expectedLoadTime(ex);
    97	      const down = Math.max(ex.state === 'broken' ? ex.brokenLeft : ex.state === 'nostock' ? 4 * 3600 : 0, ex.blastLeft);
    98	      const free0 = now + down + (ex.loading !== null ? ex.loadLeft : 0) + ex.queue.length * lt;
    99	      // Прогоняем очередь с учётом уже едущих самосвалов: когда начнём грузиться мы
   100	      // и насколько наш приезд задержит тех, кто приедет позже (их ожидание — тоже потеря).
   101	      const arr = arrivals[ex.id].sort((x, y) => x - y);
   102	      let free = free0;
   103	      let freeWithout = free0;
   104	      let start = -1;
   105	      let pushed = 0;
   106	      for (const a of arr) {
   107	        if (start < 0 && a > arrive) {
   108	          start = Math.max(free, arrive);
   109	          free = start + lt;
   110	        }
   111	        const s1 = Math.max(free, a);
   112	        const s0 = Math.max(freeWithout, a);
   113	        if (start >= 0) pushed += s1 - s0;
   114	        free = s1 + lt;
   115	        freeWithout = s0 + lt;
   116	      }
   117	      if (start < 0) start = Math.max(free, arrive);
   118	      // График взрывов известен: если погрузка попадёт в оцепление — начнём только после него.
   119	      const win = sim.blastWindow(ex.id, now);
   120	      if (win && start + lt > win[0] && start < win[1]) start = win[1];
   121	      // Время до окончания погрузки (доезд + ожидание + погрузка) + задержка, которую мы создадим другим.
   122	      // Длину петли не сравниваем: сколько машин нужно на каждую петлю, задаёт план (shareBonus).
   123	      const score = start + lt - now + pushed - bonus[ex.material] - share[ex.id] - grade[ex.id];
   124	      scores.push(score);
   125	      waits.push(start - arrive);
   126	      if (score < bestScore) {
   127	        bestScore = score;
   128	        best = ex.id;
   129	      }
   130	    }
